import{_ as e,c as l,o as a,a1 as n}from"./chunks/framework.C3Hmo1as.js";const h=JSON.parse('{"title":"量化交易基础知识","description":"一些零碎的知识","frontmatter":{"title":"量化交易基础知识","description":"一些零碎的知识","date":"2026-06-08T00:00:00.000Z","tags":[],"outline":[2,3]},"headers":[],"relativePath":"trader/quant-concepts.md","filePath":"trader/quant-concepts.md"}'),r={name:"trader/quant-concepts.md"};function s(o,t,d,i,g,f){return a(),l("div",null,[...t[0]||(t[0]=[n('<h2 id="冷热路径" tabindex="-1">冷热路径 <a class="header-anchor" href="#冷热路径" aria-label="Permalink to &quot;冷热路径&quot;">​</a></h2><blockquote><p>冷热路径 - 区分Level-2数据中两种截然不同的推送机制</p></blockquote><ul><li>热路径（Hot Path） - 指“逐笔数据”，代表“事件驱动”，一有风吹草动就立刻上报</li><li>冷路径（Cold Path）- 指“快照数据”，代表“时间驱动”，到了时间点才汇总报告一次</li></ul><h3 id="对比表格" tabindex="-1">对比表格 <a class="header-anchor" href="#对比表格" aria-label="Permalink to &quot;对比表格&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">🔥 热路径 (Hot Path)</th><th style="text-align:left;">❄️ 冷路径 (Cold Path)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>核心比喻</strong></td><td style="text-align:left;"><strong>逐笔流水账</strong></td><td style="text-align:left;"><strong>定时快照/切片</strong></td></tr><tr><td style="text-align:left;"><strong>对应数据</strong></td><td style="text-align:left;">逐笔成交、逐笔委托</td><td style="text-align:left;">十档盘口快照 (Level-2)，五档盘口快照 (Level-1)</td></tr><tr><td style="text-align:left;"><strong>触发机制</strong></td><td style="text-align:left;"><strong>事件驱动</strong>：市场上每发生一笔成交或一笔委托，就立即推送一条数据。</td><td style="text-align:left;"><strong>时间驱动/切片</strong>：交易所按固定频率（如A股主板通常为<strong>3秒</strong>一次）生成一张当时的“快照”。</td></tr><tr><td style="text-align:left;"><strong>数据特点</strong></td><td style="text-align:left;"><strong>极其轻量、实时、量大</strong>：完整记录市场每一个微观动作，单日数据量可达数十GB。</td><td style="text-align:left;"><strong>静态、聚合、量小</strong>：只记录这3秒内的<strong>起始和最终状态</strong>，不展示中间过程。例如，Level-1的“分笔成交”实际上是这3秒内成交量和最后一笔价格的汇总。</td></tr><tr><td style="text-align:left;"><strong>数据精度</strong></td><td style="text-align:left;">毫秒/微秒级，真实还原交易过程。</td><td style="text-align:left;">秒级（3秒），只看到一个时间点的截面。</td></tr><tr><td style="text-align:left;"><strong>能看到什么</strong></td><td style="text-align:left;">能看到一笔1000手的大单是被谁、分几次、以什么价格买走的。</td><td style="text-align:left;">只能看到这3秒内总共成交了1000手，但看不出具体细节。</td></tr></tbody></table><h3 id="冷热数据的用途" tabindex="-1">冷热数据的用途 <a class="header-anchor" href="#冷热数据的用途" aria-label="Permalink to &quot;冷热数据的用途&quot;">​</a></h3><ul><li><p><strong>看见“主力行踪”</strong>：只有“热路径”的逐笔数据，才能帮你还原主力资金真实的挂单、撤单和成交痕迹。比如，通过逐笔委托可以发现主力在买一价位挂了1万手，但又在下一秒撤单——这种“虚假订单”在3秒一次的“冷路径”快照里是看不出来的。</p></li><li><p><strong>识破“虚假盘口”</strong>：普通的十档快照（冷路径）只能告诉你现在买一有1000手挂着。而逐笔委托（热路径）能告诉你这1000手是1个大户挂的，还是1000个小散户挂的。前者可能是支撑，后者可能是陷阱。</p></li></ul>',7)])])}const x=e(r,[["render",s]]);export{h as __pageData,x as default};
